}{
\begin{tikzpicture}

    % Vẽ hình chiếc lá đối xứng với màu xanh lá cây
    \fill[green!40!yellow] 
    (0,2) .. controls (0.6,1.5) and (1.2,0.5) .. (0,-2) % Nửa phải của lá
    (0,-2) .. controls (-1.2,0.5) and (-0.6,1.5) .. (0,2);  % Nửa trái của lá

    % Viền của lá
    \draw[thick, green!70!black] 
    (0,2) .. controls (0.6,1.5) and (1.2,0.5) .. (0,-2)  % Nửa phải của lá
    (0,-2) .. controls (-1.2,0.5) and (-0.6,1.5) .. (0,2);  % Nửa trái của lá

    % Vẽ gân lá
    \draw[thick, green!50!black]
    (0,2) -- (0,-2);  % Gân chính giữa

    % Vẽ các gân lá đối xứng (bên phải)
    \draw[thick, green!50!black] 
    (0,0) .. controls (0.3,0.5) .. (0.6,0.8);  % Gân phải trên
    \draw[thick, green!50!black] 
    (0,-0.5) .. controls (0.3,-0.8) .. (0.6,-0.5);  % Gân phải dưới

    % Vẽ các gân lá đối xứng (bên trái)
    \draw[thick, green!50!black] 
    (0,0) .. controls (-0.3,0.5) .. (-0.6,0.8);  % Gân trái trên
    \draw[thick, green!50!black] 
    (0,-0.5) .. controls (-0.3,-0.8) .. (-0.6,-0.5);  % Gân trái dưới

    % Thêm các chi tiết hoạt hình (những giọt sương)
    \fill[blue!70!cyan] (0.4,1.2) circle(1.5pt);  % Giọt sương bên phải
        \fill[blue!70!cyan] (-0.4,1.2) circle(1.5pt);  % Giọt sương bên phải
    \fill[blue!70!cyan] (-0.5,0.3) circle(1.5pt);  % Giọt sương bên trái
    \fill[blue!70!cyan] (0.5,0.3) circle(1.5pt);  % Giọt sương phía dưới
        \fill[blue!70!cyan] (-0.2,-0.3) circle(1.5pt);  % Giọt sương bên trái
    \fill[blue!70!cyan] (0.2,-0.3) circle(1.5pt);  % Giọt sương phía dưới
\end{tikzpicture}
}
